sp_widget.client_script:
api.controller = function($scope, $timeout, $window) {

    var c = this;


    // =====================================================
    // ACTIVE PAGE NAVIGATION
    // =====================================================

    c.activePage = "";


    // =====================================================
    // GET CURRENT SERVICE NOW PAGE
    // =====================================================

    function getCurrentPage() {

        var pageId = "";

        try {

            var urlParams =
                new URLSearchParams(
                    $window.location.search
                );

            pageId =
                urlParams.get("id") || "";

        } catch (e) {

            // Fallback for older browsers

            var match =
                $window.location.search.match(
                    /[?&]id=([^&]+)/i
                );

            if (match && match[1]) {

                pageId =
                    decodeURIComponent(
                        match[1]
                    );

            }

        }


        // Remove any unwanted whitespace

        return String(
            pageId || ""
        ).trim();

    }


    // =====================================================
    // SET ACTIVE PAGE
    // =====================================================

    function updateActivePage() {

        var currentPage =
            getCurrentPage();


        // Special handling for Student Help & Support

        if (
            currentPage ===
            "student_help_and_support"
        ) {

            c.activePage =
                "student_help_and_support";

            return;

        }


        // Normal pages

        c.activePage =
            currentPage;

    }


    // =====================================================
    // INITIAL ACTIVE PAGE
    // =====================================================

    updateActivePage();


    // =====================================================
    // INITIAL STATE - AI CHAT
    // =====================================================

    c.aiChatOpen = false;

    c.question = "";

    c.sending = false;


    // =====================================================
    // MESSAGES
    // =====================================================

    c.data.messages =
        c.data.messages || [];


    // =====================================================
    // TOGGLE FLOATING AI CHAT
    // =====================================================

    c.toggleAIChat = function() {

        c.aiChatOpen =
            !c.aiChatOpen;


        if (c.aiChatOpen) {

            $timeout(
                function() {

                    var input =
                        document.querySelector(
                            ".vg-ai-input"
                        );


                    if (input) {

                        input.focus();

                    }


                    scrollChatToBottom();

                },
                100
            );

        }

    };


    // =====================================================
    // CLOSE CHAT
    // =====================================================

    c.closeAIChat = function() {

        c.aiChatOpen = false;

    };


    // =====================================================
    // SUGGESTION QUESTION
    // =====================================================

    c.askSuggestion = function(question) {

        if (!question) {

            return;

        }


        c.question =
            question;


        c.sendQuestion();

    };


    // =====================================================
    // SEND QUESTION
    // =====================================================

    c.sendQuestion = function() {

        var question =
            String(
                c.question || ""
            ).trim();


        if (!question) {

            return;

        }


        if (c.sending) {

            return;

        }


        c.sending = true;


        // -------------------------------------------------
        // ADD USER MESSAGE
        // -------------------------------------------------

        c.data.messages.push({

            type: "user",

            text: question

        });


        // -------------------------------------------------
        // CLEAR INPUT
        // -------------------------------------------------

        c.question = "";


        // -------------------------------------------------
        // SEARCHING MESSAGE
        // -------------------------------------------------

        c.data.messages.push({

            type: "searching",

            text:
                "VisaGuardian AI is checking your information..."

        });


        scrollChatToBottom();


        // =================================================
        // SEND TO SERVER
        // =================================================

        c.server.get({

            action: "ask",

            question: question

        }).then(

            function(response) {

                c.sending = false;


                // -------------------------------------------------
                // REMOVE SEARCHING MESSAGE
                // -------------------------------------------------

                removeSearchingMessage();


                var result =
                    response &&
                    response.data
                        ? response.data
                        : null;


                // -------------------------------------------------
                // ERROR
                // -------------------------------------------------

                if (
                    !result ||
                    !result.success
                ) {

                    c.data.messages.push({

                        type: "error",

                        text:
                            (
                                result &&
                                result.error
                            ) ||
                            "I couldn't process your question. Please try again."

                    });


                    scrollChatToBottom();

                    return;

                }


                // =================================================
                // AI ANSWER
                // =================================================

                c.data.messages.push({

                    type: "answer",

                    title:
                        result.title ||
                        "VisaGuardian AI",

                    introduction:
                        result.introduction ||
                        "",

                    sections:
                        result.sections ||
                        [],

                    summary:
                        result.summary ||
                        ""

                });


                scrollChatToBottom();

            },


            // =================================================
            // SERVER ERROR
            // =================================================

            function(error) {

                c.sending = false;


                removeSearchingMessage();


                c.data.messages.push({

                    type: "error",

                    text:
                        "There was a problem connecting to VisaGuardian AI. Please try again."

                });


                console.error(
                    "VisaGuardian AI Client Error:",
                    error
                );


                scrollChatToBottom();

            }

        );

    };


    // =====================================================
    // ENTER KEY
    // =====================================================

    c.handleKeyPress = function(event) {

        if (!event) {

            return;

        }


        if (
            event.which === 13 ||
            event.keyCode === 13
        ) {

            event.preventDefault();

            c.sendQuestion();

        }

    };


    // =====================================================
    // REMOVE SEARCHING MESSAGE
    // =====================================================

    function removeSearchingMessage() {

        for (
            var i =
                c.data.messages.length - 1;

            i >= 0;

            i--
        ) {

            if (
                c.data.messages[i].type ===
                "searching"
            ) {

                c.data.messages.splice(
                    i,
                    1
                );


                return;

            }

        }

    }


    // =====================================================
    // SCROLL CHAT TO BOTTOM
    // =====================================================

    function scrollChatToBottom() {

        $timeout(

            function() {

                var chat =
                    document.querySelector(
                        "#vg-chat .vg-chat-message-list"
                    );


                if (chat) {

                    chat.scrollTop =
                        chat.scrollHeight;

                }

            },

            50

        );

    }


    // =====================================================
    // WATCH URL CHANGES
    // =====================================================

    $scope.$on(
        "$locationChangeSuccess",
        function() {

            updateActivePage();

        }
    );


    // =====================================================
    // ALSO CHECK AFTER NAVIGATION
    // =====================================================

    $timeout(
        function() {

            updateActivePage();

        },
        100
    );


    // =====================================================
    // INITIALIZE MESSAGES
    // =====================================================

    if (!c.data.messages) {

        c.data.messages = [];

    }


    // =====================================================
    // DESTROY
    // =====================================================

    $scope.$on(
        "$destroy",
        function() {

            c.aiChatOpen = false;

        }
    );

};

sp_widget.css:
/* =========================================================
   VISA GUARDIAN AI
   PREMIUM STUDENT SIDEBAR
   DARK NAVY / ELECTRIC BLUE THEME
   ========================================================= */


/* =========================================================
   SIDEBAR
   ========================================================= */

.vg-sidebar {

    position: fixed;

    top: 0;
    left: 0;
    bottom: 0;

    width: 350px;

    height: 100vh;

    color: #ffffff;

    z-index: 9999;

    display: flex;

    flex-direction: column;

    overflow: hidden;

    box-sizing: border-box;

    font-family:
        "Segoe UI",
        Arial,
        Helvetica,
        sans-serif;

    background:

        radial-gradient(
            circle at 20% 10%,
            rgba(0, 115, 255, .10),
            transparent 30%
        ),

        linear-gradient(
            180deg,
            #061a38 0%,
            #04152e 48%,
            #030f23 100%
        );

    border-right:
        1px solid
        rgba(48, 129, 220, .14);

    box-shadow:
        12px 0 40px
        rgba(0, 0, 0, .18);
}


/* =========================================================
   SIDEBAR AMBIENT GLOW
   ========================================================= */

.vg-sidebar::before {

    content: "";

    position: absolute;

    top: -180px;
    left: -120px;

    width: 380px;
    height: 380px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(0, 125, 255, .12),
            transparent 70%
        );

    pointer-events: none;
}


/* =========================================================
   BRAND / LOGO AREA
   ========================================================= */

.vg-sidebar-logo {

    height: 104px;

    min-height: 104px;

    display: flex;

    align-items: center;

    padding:
        13px 22px;

    box-sizing: border-box;

    position: relative;

    z-index: 2;

    background:
        linear-gradient(
            135deg,
            rgba(8, 38, 78, .95),
            rgba(4, 22, 48, .96)
        );

    border-bottom:
        1px solid
        rgba(70, 140, 220, .14);
}


/* =========================================================
   BRAND ICON
   ========================================================= */

.vg-sidebar-brand-icon {

    width: 58px;

    min-width: 58px;

    height: 65px;

    margin-right: 13px;

    display: flex;

    align-items: center;

    justify-content: center;

    position: relative;
}


/* Logo glow behind shield */

.vg-sidebar-brand-icon::before {

    content: "";

    position: absolute;

    width: 52px;
    height: 52px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(0, 130, 255, .18),
            transparent 70%
        );

    filter:
        blur(5px);
}


/* Actual logo */

.vg-sidebar-logo-image {

    width: 55px;

    height: 62px;

    object-fit: contain;

    display: block;

    position: relative;

    z-index: 2;

    filter:

        drop-shadow(
            0 0 6px
            rgba(0, 145, 255, .65)
        )

        drop-shadow(
            0 0 13px
            rgba(0, 105, 255, .25)
        );

    transition:
        transform .3s ease,
        filter .3s ease;
}


.vg-sidebar-logo:hover
.vg-sidebar-logo-image {

    transform:
        scale(1.05);

    filter:

        drop-shadow(
            0 0 9px
            rgba(0, 170, 255, .85)
        )

        drop-shadow(
            0 0 18px
            rgba(0, 110, 255, .35)
        );
}


/* =========================================================
   LOGO TEXT
   ========================================================= */

.vg-logo-text {

    overflow: hidden;

    min-width: 0;
}


.vg-logo-title {

    font-size:
        21px;

    font-weight:
        750;

    line-height:
        23px;

    letter-spacing:
        -.5px;

    color:
        #ffffff;

    white-space:
        nowrap;
}


.vg-logo-title span {

    color:
        #1598ff;
}


.vg-logo-title strong {

    color:
        #963cff;
}


.vg-logo-subtitle {

    margin-top:
        6px;

    font-size:
        11px;

    color:
        #829ab8;

    letter-spacing:
        .2px;

    white-space:
        nowrap;
}


/* =========================================================
   NAVIGATION
   ========================================================= */

.vg-sidebar-nav {

    flex: 1;

    overflow-y: auto;

    overflow-x: hidden;

    padding:
        12px 0;

    position:
        relative;

    z-index:
        2;

    scrollbar-width:
        thin;

    scrollbar-color:
        rgba(80, 150, 230, .25)
        transparent;
}


/* =========================================================
   SCROLLBAR
   ========================================================= */

.vg-sidebar-nav::-webkit-scrollbar {

    width:
        5px;
}


.vg-sidebar-nav::-webkit-scrollbar-track {

    background:
        transparent;
}


.vg-sidebar-nav::-webkit-scrollbar-thumb {

    background:
        rgba(80, 150, 230, .25);

    border-radius:
        10px;
}


/* =========================================================
   NAVIGATION ITEM
   ========================================================= */

.vg-nav-item {

    position:
        relative;

    width:
        calc(100% - 18px);

    margin:
        3px 9px;

    min-height:
        56px;

    display:
        flex;

    align-items:
        center;

    padding:
        0 17px;

    box-sizing:
        border-box;

    border-radius:
        10px;

    color:
        #c7d6e9 !important;

    background:
        transparent;

    text-decoration:
        none !important;

    font-size:
        14px;

    font-weight:
        500;

    transition:
        background .22s ease,
        color .22s ease,
        transform .22s ease,
        border-color .22s ease;

    border:
        1px solid
        transparent;
}


/* =========================================================
   NORMAL ITEM
   ========================================================= */

.vg-nav-item:not(.active) {

    background:
        transparent;

    color:
        #c7d6e9 !important;
}


/* =========================================================
   HOVER
   ========================================================= */

.vg-nav-item:hover {

    background:
        linear-gradient(
            90deg,
            rgba(0, 110, 255, .12),
            rgba(0, 95, 200, .04)
        );

    border-color:
        rgba(30, 140, 255, .10);

    color:
        #ffffff !important;

    text-decoration:
        none !important;

    transform:
        translateX(3px);
}


/* =========================================================
   ACTIVE PAGE
   ========================================================= */

.vg-nav-item.active {

    background:

        linear-gradient(
            100deg,
            rgba(17, 107, 235, .95),
            rgba(34, 75, 205, .82)
        );

    color:
        #ffffff !important;

    font-weight:
        650;

    border:
        1px solid
        rgba(76, 163, 255, .28);

    box-shadow:

        0 8px 24px
        rgba(0, 83, 210, .20),

        inset 0 1px 0
        rgba(255,255,255,.10);
}


/* Active left indicator */

.vg-nav-item.active::before {

    content:
        "";

    position:
        absolute;

    left:
        0;

    top:
        12px;

    bottom:
        12px;

    width:
        3px;

    border-radius:
        0 4px 4px 0;

    background:
        #63c2ff;

    box-shadow:
        0 0 10px
        rgba(80, 190, 255, .75);
}


/* =========================================================
   ACTIVE HOVER
   ========================================================= */

.vg-nav-item.active:hover {

    background:

        linear-gradient(
            100deg,
            #1477ee,
            #3157d8
        );

    transform:
        translateX(2px);
}


/* =========================================================
   NAVIGATION ICON
   ========================================================= */

.vg-nav-icon {

    width:
        42px;

    min-width:
        42px;

    height:
        34px;

    display:
        inline-flex;

    align-items:
        center;

    justify-content:
        flex-start;

    color:
        #7fb7ed;

    font-size:
        17px;

    transition:
        color .22s ease,
        transform .22s ease;
}


/* =========================================================
   ICON HOVER
   ========================================================= */

.vg-nav-item:hover .vg-nav-icon {

    color:
        #43adff;

    transform:
        scale(1.06);
}


/* =========================================================
   ACTIVE ICON
   ========================================================= */

.vg-nav-item.active .vg-nav-icon {

    color:
        #ffffff;

    text-shadow:
        0 0 9px
        rgba(100, 205, 255, .35);
}


/* =========================================================
   DIGITAL TWIN
   ========================================================= */

.vg-nav-item[data-page="vg_digital_twin"]
.vg-nav-icon {

    color:
        #55c4ff;

    font-size:
        17px;
}


.vg-nav-item[data-page="vg_digital_twin"]:hover
.vg-nav-icon {

    color:
        #76d4ff;
}


/* =========================================================
   NAVIGATION TEXT
   ========================================================= */

.vg-nav-text {

    display:
        block;

    line-height:
        20px;

    white-space:
        nowrap;

    overflow:
        hidden;

    text-overflow:
        ellipsis;
}


/* =========================================================
   AI INDICATOR
   ========================================================= */

.vg-ai-indicator {

    margin-left:
        auto;

    padding:
        3px 7px;

    border-radius:
        10px;

    border:
        1px solid
        rgba(150, 70, 255, .35);

    background:
        rgba(120, 40, 255, .10);

    color:
        #b36cff;

    font-size:
        8px;

    font-weight:
        800;

    letter-spacing:
        .7px;
}


/* =========================================================
   NOTIFICATION BADGE
   ========================================================= */

.vg-notification-badge {

    margin-left:
        auto;

    width:
        22px;

    height:
        22px;

    min-width:
        22px;

    border-radius:
        50%;

    background:
        linear-gradient(
            135deg,
            #ff5360,
            #d92742
        );

    color:
        #ffffff;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    font-size:
        10px;

    font-weight:
        750;

    box-shadow:
        0 0 10px
        rgba(255, 60, 75, .25);
}


/* =========================================================
   SIDEBAR FOOTER
   ========================================================= */

.vg-sidebar-footer {

    position:
        relative;

    z-index:
        3;

    padding:
        8px 0;

    background:
        rgba(2, 12, 28, .72);

    border-top:
        1px solid
        rgba(80, 135, 205, .13);
}


/* =========================================================
   LOGOUT
   ========================================================= */

.vg-nav-item.logout-item {

    color:
        #91a7c2 !important;
}


.vg-nav-item.logout-item .vg-nav-icon {

    color:
        #e88c75;
}


/* =========================================================
   LOGOUT HOVER
   ========================================================= */

.vg-nav-item.logout-item:hover {

    background:
        linear-gradient(
            90deg,
            rgba(205, 55, 65, .12),
            rgba(140, 30, 40, .04)
        );

    border-color:
        rgba(255, 80, 90, .10);

    color:
        #ffb0b5 !important;
}


.vg-nav-item.logout-item:hover
.vg-nav-icon {

    color:
        #ff777f;
}


/* =========================================================
   MAIN CONTENT
   SIDEBAR WIDTH = 350PX
   ========================================================= */

.vg-main-content {

    margin-left:
        350px;

    min-height:
        100vh;

    width:
        calc(100% - 350px);

    box-sizing:
        border-box;
}


/* =========================================================
   PREVENT SIDEBAR FROM AFFECTING OTHER WIDGETS
   ========================================================= */

.vg-sidebar * {

    box-sizing:
        border-box;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 768px) {

    .vg-sidebar {

        width:
            250px;
    }


    .vg-sidebar-logo {

        height:
            86px;

        min-height:
            86px;

        padding:
            10px 15px;
    }


    .vg-sidebar-brand-icon {

        width:
            46px;

        min-width:
            46px;

        height:
            52px;

        margin-right:
            9px;
    }


    .vg-sidebar-logo-image {

        width:
            45px;

        height:
            50px;
    }


    .vg-logo-title {

        font-size:
            17px;

        line-height:
            20px;
    }


    .vg-logo-subtitle {

        font-size:
            9px;
    }


    .vg-nav-item {

        width:
            calc(100% - 12px);

        margin:
            3px 6px;

        min-height:
            51px;

        padding:
            0 13px;

        font-size:
            13px;
    }


    .vg-nav-icon {

        width:
            36px;

        min-width:
            36px;

        font-size:
            16px;
    }


    .vg-main-content {

        margin-left:
            250px;

        width:
            calc(100% - 250px);
    }


    .vg-ai-indicator {

        display:
            none;
    }
}

/* =========================================================
   VISAGUARDIAN AI — FLOATING ASSISTANT
   ========================================================= */

.vg-ai-floating-wrapper {
    position: fixed;

    right: 20px;
    bottom: 20px;

    z-index: 99999;

    display: flex;
    align-items: center;
    justify-content: center;
}


/* =========================================================
   MAIN AI FLOATING BUTTON
   ========================================================= */

.vg-ai-floating-btn {
    position: relative;

    width: 44px;
    height: 44px;

    padding: 0;
    margin: 0;

    border: none;
    border-radius: 50%;

    cursor: pointer;

    display: flex;
    align-items: center;
    justify-content: center;

    background:
        radial-gradient(
            circle at 35% 30%,
            #8b7cff 0%,
            #6654e8 35%,
            #4b3bd0 65%,
            #3929ad 100%
        );

    box-shadow:
        0 0 0 5px rgba(112, 91, 255, 0.10),
        0 0 15px rgba(101, 79, 238, 0.38),
        0 6px 20px rgba(36, 28, 110, 0.22);

    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease;
}


/* =========================================================
   OUTER COSMIC RING
   ========================================================= */

.vg-ai-floating-btn::before {
    content: "";

    position: absolute;

    inset: -4px;

    border-radius: 50%;

    border: 1px solid rgba(126, 112, 255, 0.20);

    box-shadow:
        0 0 12px rgba(117, 100, 255, 0.18);

    pointer-events: none;
}


/* =========================================================
   THREE-STAR AI ICON
   ========================================================= */

.vg-ai-stars {
    width: 40px;
    height: 40px;

    display: block;

    filter:
        drop-shadow(
            0 0 3px rgba(255, 255, 255, 0.45)
        )
        drop-shadow(
            0 0 6px rgba(179, 165, 255, 0.30)
        );

    transition:
        transform 0.25s ease,
        filter 0.25s ease;
}


/* =========================================================
   HOVER — BUTTON
   ========================================================= */

.vg-ai-floating-wrapper:hover .vg-ai-floating-btn {
    transform: translateY(-3px) scale(1.05);

    box-shadow:
        0 0 0 6px rgba(112, 91, 255, 0.12),
        0 0 22px rgba(101, 79, 238, 0.52),
        0 8px 25px rgba(36, 28, 110, 0.28);
}


/* =========================================================
   HOVER — AI ICON
   ========================================================= */

.vg-ai-floating-wrapper:hover .vg-ai-stars {
    transform: scale(1.08) rotate(3deg);

    filter:
        drop-shadow(
            0 0 5px rgba(255, 255, 255, 0.70)
        )
        drop-shadow(
            0 0 12px rgba(179, 165, 255, 0.50)
        );
}


/* =========================================================
   HOVER LABEL
   ========================================================= */

.vg-ai-hover-label {
    position: absolute;

    right: 54px;
    top: 50%;

    transform:
        translateY(-50%)
        translateX(8px);

    padding: 6px 10px;

    background: #111827;

    color: #ffffff;

    border: 1px solid rgba(139, 124, 255, 0.30);

    border-radius: 7px;

    font-family:
        "Segoe UI",
        Arial,
        sans-serif;

    font-size: 12px;
    font-weight: 600;

    line-height: 1;

    white-space: nowrap;

    box-shadow:
        0 6px 18px rgba(0, 0, 0, 0.25);

    opacity: 0;
    visibility: hidden;

    pointer-events: none;

    transition:
        opacity 0.2s ease,
        transform 0.2s ease,
        visibility 0.2s ease;
}


/* =========================================================
   LABEL ARROW
   ========================================================= */

.vg-ai-hover-label::after {
    content: "";

    position: absolute;

    right: -5px;
    top: 50%;

    width: 15px;
    height: 15px;

    background: #111827;

    border-top:
        1px solid rgba(139, 124, 255, 0.30);

    border-right:
        1px solid rgba(139, 124, 255, 0.30);

    transform:
        translateY(-50%)
        rotate(45deg);
}


/* =========================================================
   SHOW LABEL ON HOVER
   ========================================================= */

.vg-ai-floating-wrapper:hover .vg-ai-hover-label {
    opacity: 1;

    visibility: visible;

    transform:
        translateY(-50%)
        translateX(0);
}


/* =========================================================
   FOCUS ACCESSIBILITY
   ========================================================= */

.vg-ai-floating-btn:focus {
    outline: none;

    box-shadow:
        0 0 0 3px rgba(255, 255, 255, 0.85),
        0 0 0 6px rgba(91, 76, 220, 0.45),
        0 0 20px rgba(101, 79, 238, 0.45);
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 768px) {

    .vg-ai-floating-wrapper {
        right: 18px;
        bottom: 18px;
    }

    .vg-ai-floating-btn {
        width: 52px;
        height: 52px;
    }

    .vg-ai-stars {
        width: 40px;
        height: 40px;
    }

    .vg-ai-hover-label {
        display: none;
    }
}


/* =========================================================
   VERY SMALL SCREENS
   ========================================================= */

@media (max-width: 480px) {

    .vg-ai-floating-wrapper {
        right: 15px;
        bottom: 15px;
    }

    .vg-ai-floating-btn {
        width: 50px;
        height: 50px;
    }

    .vg-ai-stars {
        width: 35px;
        height: 35px;
    }
}



/* =========================================================
   VISA GUARDIAN AI — CHAT OVERLAY (COMPACT PANEL)
   ======================================================== */

.vg-ai-overlay {
  position: absolute;
  right: 0;
  bottom: 56px; /* Positions perfectly right above the 44px floating button */
  width: 390px;
  max-width: calc(100vw - 32px);
  height: 530px;
  z-index: 99998;
  animation: vgAIChatOpen 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.vg-ai-chat-panel {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #f8fafc;
  border-radius: 18px;
  border: 1px solid rgba(36, 67, 130, 0.16);
  box-shadow: 0 24px 60px rgba(7, 29, 73, 0.28), 0 8px 24px rgba(7, 29, 73, 0.16);
}

/* HEADER STYLING */
.vg-ai-chat-header {
  flex: 0 0 64px;
  height: 64px;
  padding: 0 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(135deg, #061B45 0%, #0B2B68 55%, #123E86 100%);
  color: #ffffff;
}

.vg-ai-chat-title {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.vg-ai-mini-icon {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #7185ff 0%, #4c5fe0 42%, #283cb9 100%);
  border: 1px solid rgba(255, 255, 255, 0.20);
  box-shadow: 0 0 10px rgba(91, 115, 255, 0.42);
}

.vg-ai-mini-stars {
  width: 22px;
  height: 22px;
  display: block;
}

.vg-ai-header-text .vg-ai-title {
  font-size: 14px;
  font-weight: 700;
  line-height: 18px;
  color: #ffffff;
}

.vg-ai-header-text .vg-ai-subtitle {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.75);
}

.vg-ai-close {
  width: 30px;
  height: 30px;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: rgba(255, 255, 255, 0.85);
  font-size: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.2s ease;
}

.vg-ai-close:hover {
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
}

/* WELCOME BANNER & SUGGESTION CHIPS */
.vg-ai-welcome-box {
  padding: 12px 14px;
  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
}

.vg-ai-greeting-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 10px;
}

.vg-ai-avatar-badge {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #eff6ff;
  border: 1px solid #dbeafe;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}

.vg-ai-greeting-text {
  font-size: 13px;
  color: #1e293b;
  font-weight: 600;
  line-height: 1.3;
}

.vg-ai-greeting-text p {
  margin: 2px 0 0 0;
  font-weight: 400;
  color: #64748b;
  font-size: 12px;
}

.vg-ai-suggestions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.vg-suggestion-chip {
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  color: #0f172a;
  padding: 4px 10px;
  font-size: 11px;
  border-radius: 14px;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.vg-suggestion-chip:hover {
  background: #e0f2fe;
  border-color: #38bdf8;
  color: #0369a1;
}

/* CHAT CONTENT BACKEND CONTAINER */
.vg-ai-chat-content {
  flex: 1 1 auto;
  min-height: 0;
  background: #ffffff;
  position: relative;
  overflow: hidden;
}

/* DISCLAIMER FOOTER */
.vg-ai-footer-disclaimer {
  flex: 0 0 auto;
  padding: 6px 12px;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
  font-size: 10px;
  color: #64748b;
  text-align: center;
}

/* OPEN ANIMATION */
@keyframes vgAIChatOpen {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* RESPONSIVE MOBILE OVERRIDE */
@media (max-width: 600px) {
  .vg-ai-overlay {
    right: 12px;
    bottom: 60px;
    width: calc(100vw - 24px);
    height: 70vh;
  }
}

/* =========================================================
   VISA GUARDIAN AI — CHAT INPUT AREA STYLING
   ======================================================== */

.vg-ai-input-area {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: #ffffff;
  border-top: 1px solid #e2e8f0;
  flex: 0 0 auto;
}

.vg-ai-input {
  flex: 1;
  height: 38px;
  padding: 0 12px;
  border: 1px solid #cbd5e1;
  border-radius: 20px;
  background: #f8fafc;
  color: #0f172a;
  font-size: 13px;
  outline: none;
  transition: all 0.2s ease;
}

.vg-ai-input:focus {
  background: #ffffff;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.vg-ai-send {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  border: none;
  border-radius: 50%;
  background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.3);
}

.vg-ai-send:hover {
  transform: scale(1.05);
  box-shadow: 0 4px 10px rgba(37, 99, 235, 0.4);
}

/* =========================================================
   VISA GUARDIAN AI — OVERLAY CHAT CONTENT SCROLL FIX
   ======================================================== */

.vg-ai-chat-content {
  flex: 1 1 auto;
  min-height: 0;
  max-height: 320px;
  overflow-y: auto;
  background: #ffffff;
}

.vg-chat-message-list {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

sp_widget.script:
(function () {

    // =========================================================
    // VISAGUARDIAN AI
    // STUDENT AI CHAT SERVER SCRIPT
    // Service Portal Widget: VG AI Chat
    // =========================================================


    // =========================================================
    // CONFIGURATION
    // =========================================================

    /*
     * IMPORTANT:
     *
     * Replace this with the actual INTERNAL NAME of the
     * "Get Current Student Risk Assessment" Action Designer action.
     *
     * Example:
     * x_snc_visaguardi_0.get_current_student_risk_assessment
     *
     * Do NOT use the display label if your action has a different
     * internal name.
     */

    var RISK_ACTION_NAME =
        "x_snc_visaguardi_0.get_current_student_risk_assessment";


    // =========================================================
    // INITIAL DATA
    // =========================================================

    data.success = false;
    data.error = "";

    data.student = {};
    data.visa_case = {};
    data.advisor = {};
    data.documents = [];

    data.title = "VisaGuardian AI";
    data.introduction = "";
    data.sections = [];
    data.summary = "";
    data.articles = [];

    data.user_id = "";


    // =========================================================
    // CHECK LOGIN
    // =========================================================

    if (
        !gs.isLoggedIn() ||
        gs.getUserName() == "guest"
    ) {

        data.error =
            "Please log in to access VisaGuardian AI.";

        return;
    }


    // =========================================================
    // CURRENT LOGGED-IN USER
    // =========================================================

    var currentUserSysId =
        gs.getUserID();

    var currentUserName =
        gs.getUserName();

    data.user_id =
        currentUserSysId;


    // =========================================================
    // ASK QUESTION
    // =========================================================

    if (
        input &&
        input.action == "ask"
    ) {

        var question =
            String(
                input.question || ""
            ).trim();


        if (!question) {

            data.error =
                "Please enter a question.";

            return;
        }


        // =====================================================
        // GET CURRENT STUDENT
        // =====================================================

        var studentResult =
            getCurrentStudent(
                currentUserSysId
            );


        if (!studentResult.found) {

            data.error =
                "Your student profile could not be found.";

            return;
        }


        // =====================================================
        // LOAD CURRENT STUDENT DATA
        // =====================================================

        data.student =
            studentResult.student;


        // =====================================================
        // NO AUTOMATIC CASE SELECTION
        // =====================================================

        var caseResult = {

            found: false,

            caseSysId: "",

            case: {}

        };


        // =====================================================
        // ADVISOR STARTS EMPTY
        // =====================================================

        data.advisor = {

            name: "",

            email: ""

        };


        // =====================================================
        // DOCUMENTS START EMPTY
        // =====================================================

        data.documents = [];


        // =====================================================
        // NORMALIZE QUESTION
        // =====================================================

        var normalizedQuestion =
            question.toLowerCase();


        // =====================================================
        // PERSONAL STUDENT QUESTIONS
        // =====================================================


        // -----------------------------------------------------
        // MY EMAIL
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my email",
                    "my email address",
                    "what is my email",
                    "what's my email",
                    "what is my email address",
                    "what's my email address"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your Email Address";

            data.introduction =
                "Here is your registered email address:";

            data.sections = [

                {
                    title: "Email",

                    text: "",

                    bullets: [

                        "Email: " +
                        safeValue(
                            data.student.email
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This email address belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY NAME
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my name",
                    "student name",
                    "who am i"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your Name";

            data.introduction =
                "Here is your name:";

            data.sections = [

                {
                    title: "Student Name",

                    text: "",

                    bullets: [

                        "Name: " +
                        safeValue(
                            data.student.name
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY PHONE
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my phone",
                    "my phone number",
                    "my mobile",
                    "my mobile number"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your Phone Number";

            data.introduction =
                "Here is your registered phone number:";

            data.sections = [

                {
                    title: "Contact Information",

                    text: "",

                    bullets: [

                        "Mobile: " +
                        safeValue(
                            data.student.mobile_phone
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This contact information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY UNIVERSITY
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my university",
                    "what university do i attend",
                    "which university do i attend"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your University";

            data.introduction =
                "Here is your university information:";

            data.sections = [

                {
                    title: "University",

                    text: "",

                    bullets: [

                        "University: " +
                        safeValue(
                            data.student.university_name
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY DEGREE
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my degree",
                    "my degree program",
                    "what is my degree",
                    "what am i studying"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Your Degree Program";

            data.introduction =
                "Here is your current degree information:";

            data.sections = [

                {
                    title: "Academic Information",

                    text: "",

                    bullets: [

                        "Degree Program: " +
                        safeValue(
                            data.student.degree_program
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY SEMESTER
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my semester",
                    "current semester",
                    "what semester am i in",
                    "which semester am i in",
                    "what is my current semester",
                    "what's my current semester"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "Current Semester";

            data.introduction =
                "Here is your current semester information:";

            data.sections = [

                {
                    title: "Academic Information",

                    text: "",

                    bullets: [

                        "Current Semester: " +
                        safeValue(
                            data.student.current_semester
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // -----------------------------------------------------
        // MY DETAILS / PROFILE
        // -----------------------------------------------------

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my details",
                    "my profile",
                    "my information",
                    "my student information",
                    "show my details",
                    "show my profile"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "My Student Information";

            data.introduction =
                "Here is your current student information:";

            data.sections = [

                {
                    title: "Student Information",

                    text: "",

                    bullets: [

                        "Name: " +
                        safeValue(
                            data.student.name
                        ),

                        "Student ID: " +
                        safeValue(
                            data.student.student_id
                        ),

                        "Email: " +
                        safeValue(
                            data.student.email
                        ),

                        "Mobile: " +
                        safeValue(
                            data.student.mobile_phone
                        ),

                        "University: " +
                        safeValue(
                            data.student.university_name
                        ),

                        "Degree Program: " +
                        safeValue(
                            data.student.degree_program
                        ),

                        "Current Semester: " +
                        safeValue(
                            data.student.current_semester
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information belongs to the currently logged-in student.";

            return;
        }


        // =====================================================
        // VISA QUESTIONS
        // =====================================================

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my visa",
                    "visa status",
                    "visa type",
                    "sevis",
                    "sevis id",
                    "visa expiry",
                    "passport expiry",
                    "my immigration"
                ]
            )
        ) {

            data.success = true;

            data.title =
                "My Visa Information";

            data.introduction =
                "Here is your current visa information:";

            data.sections = [

                {
                    title: "Visa Information",

                    text: "",

                    bullets: [

                        "Current Visa Status: " +
                        safeValue(
                            data.student.current_visa_status
                        ),

                        "Visa Type: " +
                        safeValue(
                            data.student.visa_type
                        ),

                        "SEVIS ID: " +
                        safeValue(
                            data.student.sevis_id
                        ),

                        "Visa Expiry Date: " +
                        safeValue(
                            data.student.visa_expiry_date
                        ),

                        "Passport Expiry Date: " +
                        safeValue(
                            data.student.passport_expiry_date
                        )

                    ],

                    steps: []
                }

            ];

            data.summary =
                "This information was retrieved for your currently logged-in student profile.";

            return;
        }


        // =====================================================
        // RISK ASSESSMENT
        // =====================================================

        if (
            isRiskAssessmentQuestion(
                normalizedQuestion
            )
        ) {

            var riskResult =
                getCurrentStudentRiskAssessment();


            if (
                riskResult.success
            ) {

                data.success = true;

                data.title =
                    "Student Risk Assessment";

                data.introduction =
                    "Here is your current operational risk assessment:";

                data.sections = [

                    {

                        title:
                            "Risk Assessment",

                        text: "",

                        bullets: [

                            "Risk Score: " +
                            safeValue(
                                riskResult.risk_score,
                                "Not available"
                            ) +
                            "/100",

                            "Risk Level: " +
                            safeValue(
                                riskResult.risk_level,
                                "Not available"
                            ).toUpperCase(),

                            "Why this score was assigned: " +
                            safeValue(
                                riskResult.risk_explanation,
                                "No explanation available."
                            )

                        ],

                        steps: []

                    }

                ];


                data.summary =
                    safeValue(
                        riskResult.risk_assessment_response,
                        "Your current risk assessment has been calculated."
                    );


                return;

            }


            data.success = true;

            data.title =
                "Risk Assessment";

            data.introduction =
                "I could not retrieve your current risk assessment.";

            data.sections = [

                {

                    title:
                        "Risk Assessment",

                    text: "",

                    bullets: [

                        "The risk assessment action could not be completed.",

                        "Please try again in a moment.",

                        "If the problem continues, contact your international student advisor."

                    ],

                    steps: []

                }

            ];

            data.summary =
                "Your risk assessment could not be retrieved at this time.";

            return;
        }


        // =====================================================
        // CASE SUMMARY
        // =====================================================

        if (
            containsAny(
                normalizedQuestion,
                [
                    "summarize my case",
                    "summarize the case",
                    "summarize my visa case",
                    "can you summarize the visa case",
                    "summary of my case",
                    "summary of my visa case",
                    "give me a summary",
                    "give me the summary",
                    "give me summary",
                    "summarize my cases",
                    "summarize all my cases",
                    "summary of my cases",
                    "summary of all my cases",
                    "can you summarize my visa cases",
                    "can you summarize my cases",
                    "can you summarize my visa case",
                    "what should i do"
                ]
            )
        ) {

            var summaryCaseNumber =
                extractCaseNumber(
                    question
                );


            if (summaryCaseNumber) {

                var summaryCaseResult =
                    getVisaCaseByNumber(
                        summaryCaseNumber,
                        studentResult.profileSysId
                    );


                if (!summaryCaseResult.found) {

                    data.success = true;

                    data.title =
                        "Visa Case Summary";

                    data.introduction =
                        "I could not find " +
                        summaryCaseNumber +
                        " in your student profile.";

                    data.sections = [];

                    data.summary =
                        "For security, VisaGuardian only provides summaries for cases belonging to the currently logged-in student.";

                    return;
                }


                data.visa_case =
                    summaryCaseResult.case;


                data.advisor =
                    getAdvisor(
                        summaryCaseResult.case,
                        summaryCaseResult.caseSysId
                    );


                data.documents =
                    getStudentDocuments(
                        studentResult.profileSysId,
                        summaryCaseResult.caseSysId,
                        summaryCaseResult.case.case_type_raw
                    );


                var specificSummaryText =
                    buildCaseSummary(
                        data.student,
                        data.visa_case,
                        data.advisor,
                        data.documents
                    );


                data.success = true;

                data.title =
                    "AI Case Summary";

                data.introduction =
                    "Here is a summary of your selected VisaGuardian case:";

                data.sections = [

                    {

                        title:
                            "Case Summary",

                        text: "",

                        bullets:
                            convertToPoints(
                                specificSummaryText
                            ),

                        steps: []

                    }

                ];

                data.summary =
                    "Review the case information and follow any outstanding requirements. For important immigration decisions, confirm requirements with your university international student advisor.";

                return;
            }


            var summaryCases =
                getStudentVisaCases(
                    studentResult.profileSysId
                );


            if (
                !summaryCases ||
                summaryCases.length === 0
            ) {

                data.success = true;

                data.title =
                    "Visa Case Summary";

                data.introduction =
                    "No visa cases were found for your student profile.";

                data.sections = [];

                data.summary =
                    "If you believe a case should exist, please contact your international student advisor.";

                return;
            }


            if (
                summaryCases.length === 1
            ) {

                var singleSummaryCase =
                    getVisaCaseByNumber(
                        summaryCases[0].case_id,
                        studentResult.profileSysId
                    );


                if (
                    singleSummaryCase.found
                ) {

                    data.visa_case =
                        singleSummaryCase.case;


                    data.advisor =
                        getAdvisor(
                            singleSummaryCase.case,
                            singleSummaryCase.caseSysId
                        );


                    data.documents =
                        getStudentDocuments(
                            studentResult.profileSysId,
                            singleSummaryCase.caseSysId,
                            singleSummaryCase.case.case_type_raw
                        );


                    var singleSummaryText =
                        buildCaseSummary(
                            data.student,
                            data.visa_case,
                            data.advisor,
                            data.documents
                        );


                    data.success = true;

                    data.title =
                        "AI Case Summary";

                    data.introduction =
                        "Here is a summary of your current visa case:";

                    data.sections = [

                        {

                            title:
                                "Case Summary",

                            text: "",

                            bullets:
                                convertToPoints(
                                    singleSummaryText
                                ),

                            steps: []

                        }

                    ];

                    data.summary =
                        "Review the case information and follow any outstanding requirements. For important immigration decisions, confirm requirements with your university international student advisor.";

                    return;
                }


                data.success = true;

                data.title =
                    "Visa Case Summary";

                data.introduction =
                    "I could not load your visa case.";

                data.sections = [];

                data.summary =
                    "Please try again or provide the case number.";

                return;
            }


            var overallSummaryText =
                buildAllCasesSummary(
                    data.student,
                    summaryCases
                );


            data.success = true;

            data.title =
                "AI Visa Case Summary";

            data.introduction =
                "Here is an overview of all visa cases associated with your student profile:";

            data.sections = [

                {

                    title:
                        "Visa Case Summary",

                    text: "",

                    bullets:
                        convertToPoints(
                            overallSummaryText
                        ),

                    steps: []

                }

            ];

            data.summary =
                "This summary covers all visa cases associated with your student profile. Review each case for outstanding actions and confirm important immigration requirements with your university international student advisor.";

            return;
        }


        // =====================================================
        // DOCUMENT QUESTIONS
        // =====================================================

        if (
            isDocumentQuestion(
                normalizedQuestion
            )
        ) {

            var documentCaseNumber =
                extractCaseNumber(
                    question
                );


            if (
                documentCaseNumber
            ) {

                var documentCaseResult =
                    getVisaCaseByNumber(
                        documentCaseNumber,
                        studentResult.profileSysId
                    );


                if (
                    !documentCaseResult.found
                ) {

                    data.success = true;

                    data.title =
                        "Document Access";

                    data.introduction =
                        "I could not find " +
                        documentCaseNumber +
                        " in your student profile.";

                    data.sections = [

                        {

                            title:
                                "Access Check",

                            text: "",

                            bullets: [

                                "The case number may be incorrect.",

                                "The case may not belong to the currently logged-in student.",

                                "For security, VisaGuardian only provides document information for your own visa cases."

                            ],

                            steps: []

                        }

                    ];

                    data.summary =
                        "No document records were returned for this case.";

                    return;
                }


                data.visa_case =
                    documentCaseResult.case;


                data.documents =
                    getStudentDocuments(
                        studentResult.profileSysId,
                        documentCaseResult.caseSysId,
                        documentCaseResult.case.case_type_raw
                    );


                return buildDocumentResponse(
                    question,
                    documentCaseNumber,
                    data.documents,
                    data.visa_case
                );

            }


            var documentCases =
                getStudentVisaCases(
                    studentResult.profileSysId
                );


            if (
                !documentCases ||
                documentCases.length === 0
            ) {

                data.success = true;

                data.title =
                    "My Documents";

                data.introduction =
                    "I could not find a visa case associated with your student profile.";

                data.sections = [

                    {

                        title:
                            "Document Access",

                        text: "",

                        bullets: [

                            "No visa case is currently associated with your student profile.",

                            "Document information can be checked once a visa case is available."

                        ],

                        steps: []

                    }

                ];

                data.summary =
                    "Please contact your international student advisor if you believe a visa case should be available.";

                return;
            }


            if (
                documentCases.length === 1
            ) {

                var documentOnlyCase =
                    getVisaCaseByNumber(
                        documentCases[0].case_id,
                        studentResult.profileSysId
                    );


                if (
                    !documentOnlyCase.found
                ) {

                    data.success = true;

                    data.title =
                        "My Documents";

                    data.introduction =
                        "I could not load the visa case associated with your student profile.";

                    data.sections = [];

                    data.summary =
                        "Please try again or contact your international student advisor.";

                    return;
                }


                data.visa_case =
                    documentOnlyCase.case;


                data.documents =
                    getStudentDocuments(
                        studentResult.profileSysId,
                        documentOnlyCase.caseSysId,
                        documentOnlyCase.case.case_type_raw
                    );


                return buildDocumentResponse(
                    question,
                    documentOnlyCase.case.case_id,
                    data.documents,
                    data.visa_case
                );

            }


            var documentCaseBullets = [];


            for (
                var dc = 0;
                dc < documentCases.length;
                dc++
            ) {

                documentCaseBullets.push(

                    (dc + 1) +
                    ". " +
                    safeValue(
                        documentCases[dc].case_id,
                        "Unknown Case"
                    ) +
                    " — Type: " +
                    safeValue(
                        documentCases[dc].case_type,
                        "Not available"
                    ) +
                    " — Status: " +
                    safeValue(
                        documentCases[dc].case_stage,
                        "Not available"
                    )

                );

            }


            data.success = true;

            data.title =
                "Choose a Visa Case";

            data.introduction =
                "You have multiple visa cases. Please tell me which case you want to check documents for:";

            data.sections = [

                {

                    title:
                        "Your Visa Cases",

                    text: "",

                    bullets:
                        documentCaseBullets,

                    steps: []

                }

            ];

            data.summary =
                "Please provide the case number, for example TASK12345.";

            return;
        }


        // =====================================================
        // CASE QUESTIONS
        // =====================================================

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my case",
                    "visa case",
                    "case status",
                    "case stage",
                    "case priority",
                    "case type",
                    "case details",
                    "case information",
                    "my cases",
                    "all my cases",
                    "my visa cases",
                    "show my cases",
                    "list my cases",
                    "what are my cases",
                    "what visa cases do i have",
                    "current visa cases",
                    "what are my current visa cases"
                ]
            )
            ||
            extractCaseNumber(question)
        ) {

            var requestedCaseNumber =
                extractCaseNumber(
                    question
                );


            if (requestedCaseNumber) {

                var specificCaseResult =
                    getVisaCaseByNumber(
                        requestedCaseNumber,
                        studentResult.profileSysId
                    );


                if (!specificCaseResult.found) {

                    data.success = true;

                    data.title =
                        "Visa Case";

                    data.introduction =
                        "I could not find " +
                        requestedCaseNumber +
                        " in your student profile.";

                    data.sections = [

                        {

                            title:
                                "Case Access",

                            text: "",

                            bullets: [

                                "The case number may be incorrect.",

                                "The case may not belong to your student profile.",

                                "For security, VisaGuardian only provides access to your own visa cases."

                            ],

                            steps: []

                        }

                    ];

                    data.summary =
                        "You can ask me to list your available visa cases.";

                    return;
                }


                caseResult =
                    specificCaseResult;


                data.visa_case =
                    caseResult.case;


                data.advisor =
                    getAdvisor(
                        caseResult.case,
                        caseResult.caseSysId
                    );


                data.documents =
                    getStudentDocuments(
                        studentResult.profileSysId,
                        caseResult.caseSysId,
                        caseResult.case.case_type_raw
                    );


                data.success = true;

                data.title =
                    "My Visa Case";

                data.introduction =
                    "Here is the visa case you requested:";

                data.sections = [

                    {

                        title:
                            "Case Information",

                        text: "",

                        bullets: [

                            "Case ID: " +
                            safeValue(
                                data.visa_case.case_id
                            ),

                            "Case Type: " +
                            safeValue(
                                data.visa_case.case_type
                            ),

                            "Visa Category: " +
                            safeValue(
                                data.visa_case.visa_category
                            ),

                            "Priority: " +
                            safeValue(
                                data.visa_case.priority
                            ),

                            "Status: " +
                            safeValue(
                                data.visa_case.case_stage
                            ),

                            "Assigned Advisor: " +
                            safeValue(
                                data.advisor.name,
                                "Not Assigned"
                            ),

                            "Created On: " +
                            safeValue(
                                data.visa_case.created_on
                            ),

                            "Last Updated: " +
                            safeValue(
                                data.visa_case.updated_on
                            )

                        ],

                        steps: []

                    }

                ];

                data.summary =
                    safeValue(
                        data.visa_case.description,
                        "Your selected visa case information is shown above."
                    );

                return;
            }


            var studentCases =
                getStudentVisaCases(
                    studentResult.profileSysId
                );


            if (
                !studentCases ||
                studentCases.length === 0
            ) {

                data.success = true;

                data.title =
                    "My Visa Cases";

                data.introduction =
                    "I could not find any visa cases associated with your student profile.";

                data.sections = [];

                data.summary =
                    "If you believe you should have a visa case, please contact your international student advisor.";

                return;
            }


            var caseBullets = [];


            for (
                var c = 0;
                c < studentCases.length;
                c++
            ) {

                var currentCase =
                    studentCases[c];


                caseBullets.push(

                    (c + 1) +
                    ". " +
                    safeValue(
                        currentCase.case_id,
                        "Unknown Case"
                    ) +
                    " — Type: " +
                    safeValue(
                        currentCase.case_type,
                        "Not available"
                    ) +
                    " — Status: " +
                    safeValue(
                        currentCase.case_stage,
                        "Not available"
                    )

                );

            }


            data.success = true;

            data.title =
                "My Visa Cases";

            data.introduction =
                "I found the following visa cases associated with your student profile:";

            data.sections = [

                {

                    title:
                        "Available Visa Cases",

                    text: "",

                    bullets:
                        caseBullets,

                    steps: []

                }

            ];

            data.summary =
                "Please tell me the case number you want to view, for example TASK0020673.";

            return;
        }


        // =====================================================
        // ADVISOR QUESTIONS
        // =====================================================

        if (
            containsAny(
                normalizedQuestion,
                [
                    "my advisor",
                    "assigned advisor",
                    "who is my advisor",
                    "advisor name",
                    "advisor email",
                    "my advisors",
                    "show my advisors",
                    "assigned advisors",
                    "show assigned advisors"
                ]
            )
        ) {

            var advisorCaseNumber =
                extractCaseNumber(
                    question
                );


            if (advisorCaseNumber) {

                var advisorCaseResult =
                    getVisaCaseByNumber(
                        advisorCaseNumber,
                        studentResult.profileSysId
                    );


                if (
                    advisorCaseResult.found
                ) {

                    data.visa_case =
                        advisorCaseResult.case;


                    data.advisor =
                        getAdvisor(
                            advisorCaseResult.case,
                            advisorCaseResult.caseSysId
                        );

                }

            }
            else {

                var advisorCases =
                    getStudentVisaCases(
                        studentResult.profileSysId
                    );


                if (
                    !advisorCases ||
                    advisorCases.length === 0
                ) {

                    data.success = true;

                    data.title =
                        "My Advisor";

                    data.introduction =
                        "No visa cases were found in your student profile.";

                    data.sections = [];

                    data.summary =
                        "There are no case-specific advisors to display.";

                    return;
                }


                if (
                    advisorCases.length == 1
                ) {

                    var advisorOnlyCase =
                        getVisaCaseByNumber(
                            advisorCases[0].case_id,
                            studentResult.profileSysId
                        );


                    if (
                        advisorOnlyCase.found
                    ) {

                        data.visa_case =
                            advisorOnlyCase.case;

                        data.advisor =
                            getAdvisor(
                                advisorOnlyCase.case,
                                advisorOnlyCase.caseSysId
                            );

                    }


                    data.success = true;

                    data.title =
                        "My Advisor";

                    data.introduction =
                        "Here is the advisor assigned to your visa case:";

                    data.sections = [

                        {

                            title:
                                "Advisor Information",

                            text: "",

                            bullets: [

                                "Case Number: " +
                                safeValue(
                                    data.visa_case.case_id
                                ),

                                "Advisor Name: " +
                                safeValue(
                                    data.advisor.name,
                                    "Not Assigned"
                                ),

                                "Advisor Email: " +
                                safeValue(
                                    data.advisor.email,
                                    "Not Available"
                                )

                            ],

                            steps: []

                        }

                    ];

                    data.summary =
                        "Advisor information is based on the advisor assigned to your visa case.";

                    return;
                }


                if (
                    advisorCases.length > 1
                ) {

                    var advisorCaseBullets = [];


                    for (
                        var ac = 0;
                        ac < advisorCases.length;
                        ac++
                    ) {

                        var currentAdvisorCase =
                            advisorCases[ac];


                        var advisorName =
                            safeValue(
                                currentAdvisorCase.assigned_advisor_name,
                                "Not Assigned"
                            );


                        var advisorEmail =
                            safeValue(
                                currentAdvisorCase.assigned_advisor_email,
                                ""
                            );


                        var advisorLine =

                            (ac + 1) +
                            ". " +
                            safeValue(
                                currentAdvisorCase.case_id,
                                "Unknown Case"
                            ) +
                            " — Type: " +
                            safeValue(
                                currentAdvisorCase.case_type,
                                "Not available"
                            ) +
                            " — Advisor: " +
                            advisorName;


                        if (
                            advisorEmail &&
                            advisorEmail != "Not available"
                        ) {

                            advisorLine +=
                                " — Email: " +
                                advisorEmail;

                        }


                        advisorLine +=
                            " — Status: " +
                            safeValue(
                                currentAdvisorCase.case_stage,
                                "Not available"
                            );


                        advisorCaseBullets.push(
                            advisorLine
                        );

                    }


                    data.success = true;

                    data.title =
                        "My Visa Advisors";

                    data.introduction =
                        "Here are the advisors assigned to your visa cases:";

                    data.sections = [

                        {

                            title:
                                "Your Visa Cases and Advisors",

                            text: "",

                            bullets:
                                advisorCaseBullets,

                            steps: []

                        }

                    ];

                    data.summary =
                        "The advisor information shown above is based on the advisor assigned to each visa case.";

                    return;
                }

            }


            data.success = true;

            data.title =
                "My Advisor";

            data.introduction =
                "Here is your currently assigned advisor information:";

            data.sections = [

                {

                    title:
                        "Advisor Information",

                    text: "",

                    bullets: [

                        "Advisor Name: " +
                        safeValue(
                            data.advisor.name,
                            "Not Assigned"
                        ),

                        "Advisor Email: " +
                        safeValue(
                            data.advisor.email,
                            "Not Available"
                        )

                    ],

                    steps: []

                }

            ];

            data.summary =
                "Advisor information is based on the advisor assigned to the selected visa case.";

            return;
        }


        // =====================================================
        // KNOWLEDGE BASE
        // =====================================================

        var kbResult =
            searchKnowledgeBase(
                question
            );


        if (kbResult.found) {

            data.success = true;

            data.title =
                "Visa Guidance";

            data.introduction =
                "Here are the key points related to your question:";

            data.sections =
                kbResult.sections;

            data.summary =
                kbResult.summary;

            data.articles = [];

            return;
        }


        // =====================================================
        // GEMINI FALLBACK
        // =====================================================

        var aiResult =
            callGemini(
                question,
                data.student,
                data.visa_case,
                data.advisor,
                data.documents
            );


        if (aiResult.success) {

            data.success = true;

            data.title =
                "Visa Guidance";

            data.introduction =
                "Here are the key points related to your question:";

            data.sections = [

                {

                    title:
                        "Important Points",

                    text: "",

                    bullets:
                        convertToPoints(
                            aiResult.answer
                        ),

                    steps: []

                }

            ];

            data.summary =
                "For important immigration decisions, confirm requirements with your university international student advisor or the appropriate immigration authority.";

            data.articles = [];

            return;
        }


        // =====================================================
        // CREATE SUPPORT TICKET
        // =====================================================

        var ticketResult =
            createSupportTicket(
                studentResult.profileSysId,
                question
            );


        if (ticketResult.success) {

            data.success = true;

            data.title =
                "Support Request Created";

            data.introduction =
                "I couldn't find a direct answer to that, so I've created a support ticket for your advisor to review.";

            data.sections = [

                {

                    title:
                        "Ticket Details",

                    text: "",

                    bullets: [

                        "Ticket Number: " +
                        safeValue(
                            ticketResult.ticketNumber
                        ),

                        "Your Question: " +
                        question

                    ],

                    steps: []

                }

            ];

            data.summary =
                "Your international student advisor will follow up on this ticket.";

            return;
        }


        // =====================================================
        // ERROR
        // =====================================================

        data.success = false;

        data.error =
            "I could not provide guidance for this question, and I was unable to create a support ticket automatically. Please contact your international student advisor directly.";

    }


    // =========================================================
    // GET CURRENT STUDENT RISK ASSESSMENT
    // =========================================================

    function getCurrentStudentRiskAssessment() {

        var result = {

            success: false,

            risk_score: 0,

            risk_level: "",

            risk_explanation: "",

            risk_assessment_response: "",

            error: ""

        };


        try {

            /*
             * The Action Designer action resolves the current
             * logged-in student itself.
             *
             * Therefore we intentionally do NOT send the
             * student sys_id from the browser.
             */

            var actionInputs = {};


            var actionResult =
                sn_fd.FlowAPI
                    .getRunner()
                    .action(
                        RISK_ACTION_NAME
                    )
                    .inForeground()
                    .withInputs(
                        actionInputs
                    )
                    .run();


            var outputs =
                actionResult.getOutputs();


            if (!outputs) {

                result.error =
                    "Risk assessment action returned no outputs.";

                return result;
            }


            result.risk_score =
                outputs["risk_score"];


            result.risk_level =
                outputs["risk_level"];


            result.risk_explanation =
                outputs["risk_explanation"];


            result.risk_assessment_response =
                outputs["risk_assessment_response"];


            /*
             * Make sure the action actually returned the
             * expected values.
             */

            if (
                result.risk_score === undefined &&
                result.risk_level === undefined &&
                result.risk_explanation === undefined &&
                result.risk_assessment_response === undefined
            ) {

                result.error =
                    "Risk assessment action returned unexpected outputs.";

                return result;
            }


            result.success = true;

            return result;

        }
        catch (e) {

            result.error =
                e.message ||
                String(e);


            gs.error(
                "VisaGuardian Risk Assessment Error: " +
                result.error
            );


            return result;
        }

    }


    // =========================================================
    // RISK QUESTION DETECTOR
    // =========================================================

    function isRiskAssessmentQuestion(
        normalizedQuestion
    ) {

        if (!normalizedQuestion) {

            return false;

        }


        return containsAny(
            normalizedQuestion,
            [

                "my risk",

                "current risk",

                "risk assessment",

                "risk score",

                "risk level",

                "visa risk",

                "case risk",

                "how risky is my case",

                "how risky is my visa",

                "am i at risk",

                "what is my risk",

                "what's my risk",

                "show my risk",

                "check my risk",

                "check my risk assessment",

                "assess my risk",

                "operational risk",

                "student risk"

            ]
        );

    }


    // =========================================================
    // GET CURRENT STUDENT
    // =========================================================

    function getCurrentStudent(userSysId) {

        var result = {
            found: false,
            profileSysId: "",
            student: {}
        };

        var PROFILE_TABLE =
            "x_snc_visaguardi_0_student_profile";

        try {

            var currentUserName =
                String(gs.getUserName() || "").trim();

            var currentUserEmail = "";

            try {
                var userGR =
                    new GlideRecord("sys_user");

                if (
                    userGR.get(userSysId) &&
                    userGR.isValidField("email")
                ) {
                    currentUserEmail =
                        String(
                            userGR.getValue("email") || ""
                        ).trim();
                }
            } catch (userError) {
                gs.error(
                    "VisaGuardian Current User Email Error: " +
                    userError.message
                );
            }


            // =================================================
            // HELPER: ACCEPT PROFILE SAFELY
            // =================================================

            function acceptProfile(profile) {

                if (!profile || !profile.isValidRecord()) {
                    return false;
                }

                // If the profile has a ServiceNow user reference,
                // never allow another user's profile to be returned.
                if (profile.isValidField("user")) {

                    var linkedUser =
                        String(
                            profile.getValue("user") || ""
                        ).trim();

                    if (
                        linkedUser &&
                        linkedUser != String(userSysId)
                    ) {
                        return false;
                    }
                }

                result.found = true;

                result.profileSysId =
                    profile.getUniqueValue();

                result.student =
                    readStudentProfile(profile);

                return true;
            }


            // =================================================
            // 1. SESSION STUDENT PROFILE SYS_ID
            // =================================================

            var sessionProfileSysId =
                gs.getSession()
                    .getClientData(
                        "vg_student_sys_id"
                    );

            if (sessionProfileSysId) {

                var sessionProfile =
                    new GlideRecord(PROFILE_TABLE);

                if (
                    sessionProfile.get(
                        sessionProfileSysId
                    )
                ) {

                    if (acceptProfile(sessionProfile)) {
                        return result;
                    }
                }
            }


            // =================================================
            // 2. SESSION STUDENT USERNAME
            // =================================================

            var sessionUserName =
                gs.getSession()
                    .getClientData(
                        "vg_student_user_name"
                    );

            if (sessionUserName) {

                var profileBySessionUser =
                    new GlideRecord(PROFILE_TABLE);

                if (
                    profileBySessionUser.isValidField(
                        "user_name"
                    )
                ) {

                    profileBySessionUser.addQuery(
                        "user_name",
                        String(sessionUserName).trim()
                    );

                    profileBySessionUser.setLimit(1);
                    profileBySessionUser.query();

                    if (
                        profileBySessionUser.next() &&
                        acceptProfile(profileBySessionUser)
                    ) {
                        return result;
                    }
                }
            }


            // =================================================
            // 3. DIRECT SERVICE NOW USER REFERENCE
            // =================================================

            var profile =
                new GlideRecord(PROFILE_TABLE);

            if (
                profile.isValidField("user")
            ) {

                profile.addQuery(
                    "user",
                    userSysId
                );

                profile.setLimit(1);
                profile.query();

                if (profile.next()) {

                    if (acceptProfile(profile)) {
                        return result;
                    }
                }
            }


            // =================================================
            // 4. CURRENT SERVICENOW USERNAME
            // =================================================

            profile =
                new GlideRecord(PROFILE_TABLE);

            if (
                profile.isValidField("user_name") &&
                currentUserName
            ) {

                profile.addQuery(
                    "user_name",
                    currentUserName
                );

                profile.setLimit(1);
                profile.query();

                if (profile.next()) {

                    if (acceptProfile(profile)) {
                        return result;
                    }
                }
            }


            // =================================================
            // 5. CURRENT USER EMAIL
            // =================================================
            // Useful when a student profile was recreated and
            // the username/reference was not populated correctly.

            if (currentUserEmail) {

                profile =
                    new GlideRecord(PROFILE_TABLE);

                var emailField = "";

                if (
                    profile.isValidField("email")
                ) {
                    emailField = "email";
                }
                else if (
                    profile.isValidField("email_address")
                ) {
                    emailField = "email_address";
                }

                if (emailField) {

                    profile.addQuery(
                        emailField,
                        currentUserEmail
                    );

                    profile.setLimit(1);
                    profile.query();

                    if (profile.next()) {

                        if (acceptProfile(profile)) {
                            return result;
                        }
                    }
                }
            }


            // =================================================
            // 6. CASE OWNERSHIP FALLBACK
            // =================================================
            // If the student profile reference was not linked but
            // the visa case is linked to the current user/profile,
            // recover the profile from the case safely.

            var caseGR =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_case"
                );

            var caseUserField = "";

            if (
                caseGR.isValidField("student")
            ) {
                caseUserField = "student";
            }
            else if (
                caseGR.isValidField("student_profile")
            ) {
                caseUserField = "student_profile";
            }

            if (caseUserField) {

                // First try the case's student reference against
                // the current ServiceNow user.
                if (
                    caseUserField == "student" &&
                    caseGR.isValidField("student")
                ) {

                    caseGR.addQuery(
                        "student.user",
                        userSysId
                    );

                    caseGR.setLimit(1);
                    caseGR.query();

                    if (caseGR.next()) {

                        var recoveredProfileId =
                            caseGR.getValue("student");

                        if (recoveredProfileId) {

                            var recoveredProfile =
                                new GlideRecord(PROFILE_TABLE);

                            if (
                                recoveredProfile.get(
                                    recoveredProfileId
                                ) &&
                                acceptProfile(recoveredProfile)
                            ) {
                                return result;
                            }
                        }
                    }
                }
            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian Student Error: " +
                e.message
            );

        }

        return result;
    }


