    // =========================================================
    // EXTRACT CASE NUMBER
    // =========================================================

    function extractCaseNumber(question) {

        if (!question) {

            return "";

        }


        var match =
            String(question).match(
                /\b([A-Za-z]{2,10}\d{4,10})\b/
            );


        if (
            match &&
            match[1]
        ) {

            return match[1].toUpperCase();

        }


        return "";
    }


    // =========================================================
    // GET ALL VISA CASES FOR CURRENT STUDENT
    // =========================================================

    function getStudentVisaCases(
        profileSysId
    ) {

        var cases = [];


        if (!profileSysId) {

            return cases;

        }


        try {

            var gr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_case"
                );


            var ownershipField =
                "";


            if (
                gr.isValidField("student")
            ) {

                ownershipField =
                    "student";

            }
            else if (
                gr.isValidField(
                    "student_profile"
                )
            ) {

                ownershipField =
                    "student_profile";

            }


            if (!ownershipField) {

                gs.error(
                    "VisaGuardian Security: Visa Case table has no student ownership field."
                );

                return cases;

            }


            gr.addQuery(
                ownershipField,
                profileSysId
            );


            gr.orderByDesc(
                "sys_created_on"
            );


            gr.setLimit(50);

            gr.query();


            while (
                gr.next()
            ) {

                var advisorName = "";
                var advisorEmail = "";
                var advisorSysId = "";


                if (
                    gr.isValidField("advisor")
                ) {

                    advisorSysId =
                        gr.getValue(
                            "advisor"
                        ) || "";

                }


                if (
                    !advisorSysId &&
                    gr.isValidField(
                        "assigned_advisor"
                    )
                ) {

                    advisorSysId =
                        gr.getValue(
                            "assigned_advisor"
                        ) || "";

                }


                if (
                    advisorSysId
                ) {

                    try {

                        var advisorGr =
                            new GlideRecord(
                                "x_snc_visaguardi_0_advisor_profiles"
                            );


                        if (
                            advisorGr.get(
                                advisorSysId
                            )
                        ) {

                            advisorName =
                                getField(
                                    advisorGr,
                                    [
                                        "name",
                                        "advisor_name",
                                        "full_name"
                                    ]
                                );


                            advisorEmail =
                                getField(
                                    advisorGr,
                                    [
                                        "email",
                                        "email_address"
                                    ]
                                );

                        }

                    }
                    catch (advisorError) {

                        gs.error(
                            "VisaGuardian Advisor Lookup Error: " +
                            advisorError.message
                        );

                    }

                }


                if (
                    !advisorName &&
                    gr.isValidField("advisor")
                ) {

                    advisorName =
                        gr.getDisplayValue(
                            "advisor"
                        ) || "";

                }


                if (
                    !advisorName &&
                    gr.isValidField(
                        "assigned_advisor"
                    )
                ) {

                    advisorName =
                        gr.getDisplayValue(
                            "assigned_advisor"
                        ) || "";

                }


                cases.push({

                    case_id:
                        getField(
                            gr,
                            [
                                "case_id",
                                "number",
                                "case_number"
                            ]
                        ),

                    case_type:
                        getField(
                            gr,
                            [
                                "case_type"
                            ]
                        ),

                    visa_category:
                        getField(
                            gr,
                            [
                                "visa_category",
                                "visa_type"
                            ]
                        ),

                    case_stage:
                        getField(
                            gr,
                            [
                                "case_stage",
                                "stage"
                            ]
                        ),

                    priority:
                        getField(
                            gr,
                            [
                                "priority"
                            ]
                        ),

                    status:
                        getField(
                            gr,
                            [
                                "status",
                                "state"
                            ]
                        ),

                    assigned_advisor_name:
                        advisorName,

                    assigned_advisor_email:
                        advisorEmail,

                    assigned_advisor_sys_id:
                        advisorSysId,

                    created_on:
                        getField(
                            gr,
                            [
                                "created_on",
                                "sys_created_on"
                            ]
                        ),

                    updated_on:
                        getField(
                            gr,
                            [
                                "updated_on",
                                "sys_updated_on"
                            ]
                        ),

                    sys_id:
                        gr.getUniqueValue()

                });

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian Student Cases Error: " +
                e.message
            );

        }


        return cases;
    }


    // =========================================================
    // GET VISA CASE BY NUMBER
    // =========================================================

    function getVisaCaseByNumber(
        caseNumber,
        profileSysId
    ) {

        var result = {

            found: false,

            caseSysId: "",

            case: {}

        };


        if (
            !caseNumber ||
            !profileSysId
        ) {

            return result;

        }


        try {

            var gr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_case"
                );


            var caseNumberField =
                "";


            if (
                gr.isValidField("case_id")
            ) {

                caseNumberField =
                    "case_id";

            }
            else if (
                gr.isValidField("number")
            ) {

                caseNumberField =
                    "number";

            }
            else if (
                gr.isValidField("case_number")
            ) {

                caseNumberField =
                    "case_number";

            }


            if (!caseNumberField) {

                gs.error(
                    "VisaGuardian: No case number field found."
                );

                return result;

            }


            gr.addQuery(
                caseNumberField,
                caseNumber
            );


            var ownershipField =
                "";


            if (
                gr.isValidField("student")
            ) {

                ownershipField =
                    "student";

            }
            else if (
                gr.isValidField(
                    "student_profile"
                )
            ) {

                ownershipField =
                    "student_profile";

            }


            if (!ownershipField) {

                gs.error(
                    "VisaGuardian Security: No ownership field found on Visa Case."
                );

                return result;

            }


            gr.addQuery(
                ownershipField,
                profileSysId
            );


            gr.setLimit(1);

            gr.query();


            if (
                gr.next()
            ) {

                result.found = true;

                result.caseSysId =
                    gr.getUniqueValue();

                result.case =
                    readVisaCase(
                        gr
                    );

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian Case Lookup Error: " +
                e.message
            );

        }


        return result;
    }


