    function getAdvisor(
        caseData,
        caseSysId
    ) {

        var advisor = {

            name: "",

            email: ""

        };


        try {

            if (
                caseData
            ) {

                advisor.name =
                    safeValue(
                        caseData.assigned_advisor_name,
                        ""
                    );


                advisor.email =
                    safeValue(
                        caseData.assigned_advisor_email,
                        ""
                    );


                if (
                    advisor.name
                ) {

                    return advisor;

                }

            }


            if (
                !caseData ||
                !caseData.case_id
            ) {

                return advisor;

            }


            var caseGr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_case"
                );


