    // =========================================================
    // GET STUDENT DOCUMENTS
    // =========================================================

    function getStudentDocuments(
        profileSysId,
        caseSysId,
        caseTypeRaw
    ) {

        var documents = [];


        if (
            !caseSysId
        ) {

            return documents;

        }


        try {

            var requiredLabels = [];


            var configGr =
                new GlideRecord(
                    "x_snc_visaguardi_0_document_configuration"
                );


            if (
                !configGr.isValid()
            ) {

                gs.error(
                    "VisaGuardian: Document Configuration table is invalid."
                );

                return documents;

            }


            configGr.addQuery(
                "visa_category",
                caseTypeRaw
            );


            configGr.addQuery(
                "active",
                true
            );


            configGr.addQuery(
                "required",
                true
            );


            configGr.query();


            while (
                configGr.next()
            ) {

                requiredLabels.push(
                    configGr.getDisplayValue(
                        "document_type"
                    )
                );

            }


            var labelLookup = {};


            var configGr2 =
                new GlideRecord(
                    "x_snc_visaguardi_0_document_configuration"
                );


            if (
                configGr2.isValid()
            ) {

                configGr2.query();


                while (
                    configGr2.next()
                ) {

                    var rawType =
                        String(
                            configGr2.getValue(
                                "document_type"
                            )
                        ).toLowerCase();


                    var displayLabel =
                        configGr2.getDisplayValue(
                            "document_type"
                        );


                    labelLookup[rawType] =
                        displayLabel;

                }

            }


            var submittedLabels = [];


            var gr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_document"
                );


            if (
                !gr.isValid()
            ) {

                gs.error(
                    "VisaGuardian: Visa Document table is invalid."
                );

                return documents;

            }


            gr.addQuery(
                "visa_case",
                caseSysId
            );


            gr.query();


            while (
                gr.next()
            ) {

                var rawDocType =
                    String(
                        gr.getValue(
                            "document_type"
                        )
                    );


                var displayDocType =
                    gr.getDisplayValue(
                        "document_type"
                    );


                var normalizedType =
                    labelLookup[
                        rawDocType.toLowerCase()
                    ] ||
                    displayDocType;


                var docStatus =
                    gr.getDisplayValue(
                        "document_status"
                    );


                var verificationStatusRaw =
                    gr.getValue(
                        "verification_status"
                    );


                var verificationStatusLabel =
                    gr.getDisplayValue(
                        "verification_status"
                    );


                submittedLabels.push(
                    normalizedType
                );


                documents.push({

                    name:
                        normalizedType,

                    status:
                        docStatus,

                    verification_status:
                        verificationStatusLabel,

                    required:
                        requiredLabels.indexOf(
                            normalizedType
                        ) !== -1,

                    submitted:
                        true,

                    missing:
                        (
                            verificationStatusRaw ===
                            "rejected"
                        ),

                    pending:
                        (
                            verificationStatusRaw ===
                            "pending" ||
                            verificationStatusRaw ===
                            "under_review"
                        ),

                    sys_id:
                        gr.getUniqueValue()

                });

            }


            requiredLabels.forEach(
                function (label) {

                    if (
                        submittedLabels.indexOf(
                            label
                        ) === -1
                    ) {

                        documents.push({

                            name:
                                label,

                            status:
                                "Not Submitted",

                            verification_status:
                                "Not Submitted",

                            required:
                                true,

                            submitted:
                                false,

                            missing:
                                true,

                            pending:
                                false

                        });

                    }

                }
            );


        }
        catch (e) {

            gs.error(
                "VisaGuardian Document Error: " +
                e.message
            );

        }


        return documents;
    }


    // =========================================================
    // BUILD DOCUMENT RESPONSE
    // =========================================================

    function buildDocumentResponse(
        question,
        caseNumber,
        documents,
        visaCase
    ) {

        var normalized =
            String(
                question || ""
            ).toLowerCase();


        var requiredDocuments = [];
        var submittedDocuments = [];
        var missingDocuments = [];
        var pendingDocuments = [];


        for (
            var i = 0;
            i < documents.length;
            i++
        ) {

            var doc =
                documents[i];


            var status =
                String(
                    doc.status || ""
                ).toLowerCase();


            var required =
                doc.required === true;


            var submitted =
                doc.submitted === true;


            var missing =
                doc.missing === true;


            var pending =
                doc.pending === true;


            if (required) {

                requiredDocuments.push(
                    doc
                );

            }


            if (submitted) {

                submittedDocuments.push(
                    doc
                );

            }


            if (missing) {

                missingDocuments.push(
                    doc
                );

            }


            if (pending) {

                pendingDocuments.push(
                    doc
                );

            }


            if (
                !required &&
                !submitted &&
                !missing &&
                !pending
            ) {

                if (
                    status.indexOf("submitted") !== -1 ||
                    status.indexOf("uploaded") !== -1 ||
                    status.indexOf("received") !== -1 ||
                    status.indexOf("approved") !== -1
                ) {

                    submittedDocuments.push(
                        doc
                    );

                }
                else if (
                    status.indexOf("missing") !== -1 ||
                    status.indexOf("not submitted") !== -1 ||
                    status.indexOf("not received") !== -1
                ) {

                    missingDocuments.push(
                        doc
                    );

                }
                else if (
                    status.indexOf("pending") !== -1 ||
                    status.indexOf("review") !== -1
                ) {

                    pendingDocuments.push(
                        doc
                    );

                }

            }

        }


        if (
            containsAny(
                normalized,
                [
                    "what documents do i need",
                    "which documents do i need",
                    "documents i need",
                    "documents needed",
                    "what documents are required",
                    "which documents are required",
                    "required documents",
                    "documents required"
                ]
            )
        ) {

            return showDocumentList(
                "Required Documents",
                "Here are the required document records available for your case " +
                caseNumber +
                ":",
                requiredDocuments,
                "No required document records were found for this case."
            );

        }


        if (
            containsAny(
                normalized,
                [
                    "what documents have i submitted",
                    "which documents have i submitted",
                    "what documents did i submit",
                    "which documents did i submit",
                    "documents i submitted",
                    "submitted documents",
                    "uploaded documents",
                    "what have i uploaded",
                    "what did i upload",
                    "have i submitted",
                    "did i submit",
                    "have i uploaded"
                ]
            )
        ) {

            return showDocumentList(
                "Submitted Documents",
                "Here are the documents recorded as submitted or uploaded for case " +
                caseNumber +
                ":",
                submittedDocuments,
                "No submitted or uploaded document records were found for this case."
            );

        }


        if (
            containsAny(
                normalized,
                [
                    "what documents am i missing",
                    "which documents am i missing",
                    "what am i missing",
                    "which documents are missing",
                    "what documents are missing",
                    "missing documents",
                    "documents missing"
                ]
            )
        ) {

            return showDocumentList(
                "Missing Documents",
                "Here are the document records currently marked as missing for case " +
                caseNumber +
                ":",
                missingDocuments,
                "No documents are currently marked as missing for this case."
            );

        }


        if (
            containsAny(
                normalized,
                [
                    "pending documents",
                    "documents pending"
                ]
            )
        ) {

            return showDocumentList(
                "Pending Documents",
                "Here are the documents currently pending or under review for case " +
                caseNumber +
                ":",
                pendingDocuments,
                "No pending document records were found for this case."
            );

        }


        var allDocumentBullets = [];


        if (
            documents &&
            documents.length > 0
        ) {

            for (
                var d = 0;
                d < documents.length;
                d++
            ) {

                var currentDocument =
                    documents[d];


                var line =
                    safeValue(
                        currentDocument.name,
                        "Document"
                    );


                if (
                    currentDocument.status
                ) {

                    line +=
                        " — Status: " +
                        currentDocument.status;

                }


                if (
                    currentDocument.required
                ) {

                    line +=
                        " — Required";

                }


                if (
                    currentDocument.submitted
                ) {

                    line +=
                        " — Submitted";

                }


                if (
                    currentDocument.missing
                ) {

                    line +=
                        " — Missing";

                }


                if (
                    currentDocument.pending
                ) {

                    line +=
                        " — Pending";

                }


                allDocumentBullets.push(
                    line
                );

            }

        }
        else {

            allDocumentBullets.push(
                "No document records were found for this case."
            );

        }


        data.success = true;

        data.title =
            "Document Check";

        data.introduction =
            "Here is the current document information for case " +
            caseNumber +
            ":";

        data.sections = [

            {

                title:
                    "Document Status",

                text: "",

                bullets:
                    allDocumentBullets,

                steps: []

            }

        ];


        var summaryText =
            "Total document records: " +
            documents.length +
            ".";


        if (
            requiredDocuments.length > 0
        ) {

            summaryText +=
                " Required: " +
                requiredDocuments.length +
                ".";

        }


        if (
            submittedDocuments.length > 0
        ) {

            summaryText +=
                " Submitted/uploaded: " +
                submittedDocuments.length +
                ".";

        }


        if (
            missingDocuments.length > 0
        ) {

            summaryText +=
                " Missing: " +
                missingDocuments.length +
                ".";

        }


        if (
            pendingDocuments.length > 0
        ) {

            summaryText +=
                " Pending: " +
                pendingDocuments.length +
                ".";

        }


        data.summary =
            summaryText;


        return;
    }


    // =========================================================
    // SHOW DOCUMENT LIST
    // =========================================================

    function showDocumentList(
        title,
        introduction,
        documentList,
        emptyMessage
    ) {

        var bullets = [];


        if (
            documentList &&
            documentList.length > 0
        ) {

            for (
                var i = 0;
                i < documentList.length;
                i++
            ) {

                var doc =
                    documentList[i];


                var line =
                    safeValue(
                        doc.name,
                        "Document"
                    );


                if (
                    doc.status
                ) {

                    line +=
                        " — Status: " +
                        doc.status;

                }


                bullets.push(
                    line
                );

            }

        }
        else {

            bullets.push(
                emptyMessage
            );

        }


        data.success = true;

        data.title =
            title;

        data.introduction =
            introduction;

        data.sections = [

            {

                title:
                    title,

                text: "",

                bullets:
                    bullets,

                steps: []

            }

        ];


        data.summary =
            documentList &&
            documentList.length > 0
                ?
                "The information above is based on document records associated with your verified visa case."
                :
                emptyMessage;


        return;
    }


    // =========================================================
    // SEARCH KNOWLEDGE BASE
    // =========================================================

    function searchKnowledgeBase(
        question
    ) {

        var result = {

            found: false,

            sections: [],

            summary: "",

            articles: []

        };


        try {

            var kb =
                new GlideRecord(
                    "kb_knowledge"
                );


            kb.addQuery(
                "workflow_state",
                "published"
            );


            var q =
                kb.addQuery(
                    "short_description",
                    "CONTAINS",
                    question
                );


            q.addOrCondition(
                "text",
                "CONTAINS",
                question
            );


            kb.orderByDesc(
                "sys_updated_on"
            );


            kb.setLimit(1);

            kb.query();


            if (
                kb.next()
            ) {

                result.found = true;


                var articleText =
                    kb.getValue(
                        "text"
                    ) || "";


                articleText =
                    cleanText(
                        articleText
                    );


                var points =
                    convertToPoints(
                        articleText
                    );


                result.sections = [

                    {

                        title:
                            "Important Points",

                        text: "",

                        bullets:
                            points,

                        steps: []

                    }

                ];


                result.summary =
                    "Review the points above and follow the applicable requirements for your situation.";

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian KB Error: " +
                e.message
            );

        }


        return result;
    }


    // =========================================================
    // GEMINI FALLBACK
    // =========================================================

    function callGemini(
        question,
        student,
        visaCase,
        advisor,
        documents
    ) {

        var result = {

            success: false,

            answer: "",

            error: ""

        };


        try {

            var rm =
                new sn_ws.RESTMessageV2(
                    "VisaGuardian Gemini AI",
                    "Generate Visa AI Analysis"
                );


            var studentContext =

                "Student Name: " +
                safeValue(student.name) +

                "\nStudent ID: " +
                safeValue(student.student_id) +

                "\nUniversity: " +
                safeValue(student.university_name) +

                "\nDegree Program: " +
                safeValue(student.degree_program) +

                "\nDegree Level: " +
                safeValue(student.degree_level) +

                "\nCurrent Semester: " +
                safeValue(student.current_semester) +

                "\nIntake Year: " +
                safeValue(student.intake_year) +

                "\nVisa Type: " +
                safeValue(student.visa_type) +

                "\nVisa Status: " +
                safeValue(student.current_visa_status) +

                "\nSEVIS ID: " +
                safeValue(student.sevis_id) +

                "\nVisa Expiry Date: " +
                safeValue(student.visa_expiry_date) +

                "\nPassport Expiry Date: " +
                safeValue(student.passport_expiry_date);


            var caseContext = "";


            if (
                visaCase &&
                visaCase.case_id
            ) {

                caseContext =

                    "Case ID: " +
                    safeValue(visaCase.case_id) +

                    "\nCase Type: " +
                    safeValue(visaCase.case_type) +

                    "\nVisa Category: " +
                    safeValue(visaCase.visa_category) +

                    "\nCase Stage: " +
                    safeValue(visaCase.case_stage) +

                    "\nPriority: " +
                    safeValue(visaCase.priority) +

                    "\nStatus: " +
                    safeValue(visaCase.status) +

                    "\nAssigned Advisor: " +
                    safeValue(visaCase.assigned_advisor_name) +

                    "\nAdvisor Email: " +
                    safeValue(visaCase.assigned_advisor_email);

            }
            else {

                caseContext =
                    "No specific visa case has been selected.";

            }


            var advisorContext = "";


            if (
                advisor &&
                advisor.name
            ) {

                advisorContext =

                    "Advisor: " +
                    safeValue(advisor.name) +

                    "\nAdvisor Email: " +
                    safeValue(advisor.email);

            }
            else {

                advisorContext =
                    "No specific case advisor has been selected.";

            }


            var documentContext =
                "";


            if (
                documents &&
                documents.length > 0
            ) {

                documentContext =
                    "\n\nDOCUMENTS:\n";


                for (
                    var d = 0;
                    d < documents.length;
                    d++
                ) {

                    documentContext +=

                        "\n- " +
                        safeValue(
                            documents[d].name,
                            "Document"
                        ) +
                        " | Status: " +
                        safeValue(
                            documents[d].status,
                            "Unknown"
                        ) +
                        " | Required: " +
                        String(
                            documents[d].required
                        ) +
                        " | Submitted: " +
                        String(
                            documents[d].submitted
                        ) +
                        " | Missing: " +
                        String(
                            documents[d].missing
                        ) +
                        " | Pending: " +
                        String(
                            documents[d].pending
                        );

                }

            }
            else {

                documentContext =
                    "\n\nNo specific document records have been selected.";

            }


            var prompt =

                "You are VisaGuardian AI. " +

                "Answer the student's question about international " +
                "student visa compliance. " +

                "Use the supplied student, visa case, advisor, " +
                "and document context only when relevant. " +

                "Never invent student information. " +

                "Never reveal information belonging to another student. " +

                "Do not mention Gemini. " +

                "Do not mention the Knowledge Base. " +

                "Do not mention internal systems. " +

                "Give concise, useful factual guidance. " +

                "Only provide personal student information that is " +
                "directly relevant to the student's question. " +

                "If no specific visa case has been selected, " +
                "do not assume or invent a current case. " +

                "If document information is not available, do not invent " +
                "document names or statuses. " +

                "Use numbered points when appropriate. " +

                "If the question requires steps, provide the steps " +
                "in the correct order. " +

                "For important immigration decisions, advise the " +
                "student to confirm requirements with their university " +
                "international student advisor or appropriate " +
                "immigration authority. " +

                "\n\nCURRENT STUDENT:\n" +
                studentContext +

                "\n\nSELECTED VISA CASE:\n" +
                caseContext +

                "\n\nSELECTED CASE ADVISOR:\n" +
                advisorContext +

                documentContext +

                "\n\nSTUDENT QUESTION:\n" +
                question;


            var requestBody = {

                contents: [

                    {

                        parts: [

                            {

                                text:
                                    prompt

                            }

                        ]

                    }

                ],

                generationConfig: {

                    temperature: 0.2,

                    maxOutputTokens: 1200

                }

            };


            rm.setRequestBody(
                JSON.stringify(
                    requestBody
                )
            );


            var response =
                rm.execute();


            var status =
                response.getStatusCode();


            var body =
                response.getBody();


            if (
                status < 200 ||
                status >= 300
            ) {

                result.error =
                    "HTTP " +
                    status;


                gs.error(
                    "VisaGuardian AI Error: " +
                    body
                );


                return result;

            }


            var json =
                JSON.parse(
                    body
                );


            var answer = "";


            if (
                json.candidates &&
                json.candidates.length > 0
            ) {

                var candidate =
                    json.candidates[0];


                if (
                    candidate.content &&
                    candidate.content.parts
                ) {

                    for (
                        var i = 0;
                        i <
                        candidate.content.parts.length;
                        i++
                    ) {

                        if (
                            candidate.content.parts[i].text
                        ) {

                            answer +=
                                candidate.content.parts[i].text;

                        }

                    }

                }

            }


            if (!answer) {

                result.error =
                    "Empty response.";

                return result;

            }


            result.success = true;

            result.answer =
                cleanText(
                    answer
                );


            return result;

        }
        catch (e) {

            result.error =
                e.message;


            gs.error(
                "VisaGuardian AI Exception: " +
                e.message
            );


            return result;

        }

    }


    // =========================================================
    // CREATE SUPPORT TICKET
    // =========================================================

    function createSupportTicket(
        profileSysId,
        question
    ) {

        var result = {

            success: false,

            ticketNumber: ""

        };


        try {

            var gr =
                new GlideRecord(
                    "x_snc_visaguardi_0_visa_case"
                );


            if (
                !gr.isValid()
            ) {

                return result;

            }


            gr.initialize();


            if (
                gr.isValidField("student")
            ) {

                gr.setValue(
                    "student",
                    profileSysId
                );

            }
            else if (
                gr.isValidField(
                    "student_profile"
                )
            ) {

                gr.setValue(
                    "student_profile",
                    profileSysId
                );

            }


            if (
                gr.isValidField("case_type")
            ) {

                gr.setValue(
                    "case_type",
                    "General Inquiry"
                );

            }


            if (
                gr.isValidField("priority")
            ) {

                gr.setValue(
                    "priority",
                    "4 - Low"
                );

            }


            if (
                gr.isValidField("status")
            ) {

                gr.setValue(
                    "status",
                    "Open"
                );

            }
            else if (
                gr.isValidField("state")
            ) {

                gr.setValue(
                    "state",
                    "Open"
                );

            }


            if (
                gr.isValidField("description")
            ) {

                gr.setValue(
                    "description",
                    "AI Assistant could not directly answer the following student question:\n\n" +
                    question
                );

            }
            else if (
                gr.isValidField(
                    "case_description"
                )
            ) {

                gr.setValue(
                    "case_description",
                    "AI Assistant could not directly answer the following student question:\n\n" +
                    question
                );

            }


            var newSysId =
                gr.insert();


            if (newSysId) {

                result.success = true;

                result.ticketNumber =
                    getField(
                        gr,
                        [
                            "case_id",
                            "number",
                            "case_number"
                        ]
                    ) ||
                    newSysId;

            }

        }
        catch (e) {

            gs.error(
                "VisaGuardian Ticket Creation Error: " +
                e.message
            );

        }


        return result;
    }


    // =========================================================
    // SINGLE CASE SUMMARY
    // =========================================================

    function buildCaseSummary(
        student,
        visaCase,
        advisor,
        documents
    ) {

        var points = [];


        points.push(
            "Student: " +
            safeValue(
                student.name
            )
        );


        points.push(
            "Visa type: " +
            safeValue(
                student.visa_type
            )
        );


        points.push(
            "Visa status: " +
            safeValue(
                student.current_visa_status
            )
        );


        points.push(
            "Case ID: " +
            safeValue(
                visaCase.case_id
            )
        );


        points.push(
            "Case type: " +
            safeValue(
                visaCase.case_type
            )
        );


        if (
            visaCase.visa_category
        ) {

            points.push(
                "Visa category: " +
                safeValue(
                    visaCase.visa_category
                )
            );

        }


        points.push(
            "Case priority: " +
            safeValue(
                visaCase.priority
            )
        );


        points.push(
            "Status: " +
            safeValue(
                visaCase.case_stage
            )
        );


        if (
            advisor &&
            advisor.name
        ) {

            points.push(
                "Assigned advisor: " +
                advisor.name
            );

        }


        if (
            advisor &&
            advisor.email
        ) {

            points.push(
                "Advisor email: " +
                advisor.email
            );

        }


        if (
            visaCase.created_on
        ) {

            points.push(
                "Created on: " +
                safeValue(
                    visaCase.created_on
                )
            );

        }


        if (
            visaCase.updated_on
        ) {

            points.push(
                "Last updated: " +
                safeValue(
                    visaCase.updated_on
                )
            );

        }


        if (
            documents &&
            documents.length
        ) {

            points.push(
                "Documents currently associated with the record: " +
                documents.length
            );

        }


        if (
            visaCase.description
        ) {

            points.push(
                "Case description: " +
                visaCase.description
            );

        }


        return points.join(
            "\n"
        );

    }


    // =========================================================
    // ALL CASES SUMMARY
    // =========================================================

    function buildAllCasesSummary(
        student,
        cases
    ) {

        var points = [];


        points.push(
            "Student: " +
            safeValue(
                student.name
            )
        );


        points.push(
            "Total visa cases: " +
            cases.length
        );


        for (
            var i = 0;
            i < cases.length;
            i++
        ) {

            var currentCase =
                cases[i];


            var caseSummary =

                "Case " +
                (i + 1) +
                ": " +

                safeValue(
                    currentCase.case_id,
                    "Unknown"
                ) +

                " — Type: " +

                safeValue(
                    currentCase.case_type,
                    "Not available"
                ) +

                " — Status: " +

                safeValue(
                    currentCase.case_stage,
                    "Not available"
                ) +

                " — Priority: " +

                safeValue(
                    currentCase.priority,
                    "Not available"
                );


            if (
                currentCase.assigned_advisor_name
            ) {

                caseSummary +=
                    " — Advisor: " +
                    safeValue(
                        currentCase.assigned_advisor_name
                    );

            }


            if (
                currentCase.visa_category
            ) {

                caseSummary +=
                    " — Visa Category: " +
                    safeValue(
                        currentCase.visa_category
                    );

            }


            points.push(
                caseSummary
            );

        }


        var openCount = 0;
        var rejectedCount = 0;


        for (
            var j = 0;
            j < cases.length;
            j++
        ) {

            var stage =
                String(
                    cases[j].case_stage || ""
                ).toLowerCase();


            var status =
                String(
                    cases[j].status || ""
                ).toLowerCase();


            if (
                stage.indexOf("reject") !== -1 ||
                status.indexOf("reject") !== -1
            ) {

                rejectedCount++;

            }


            if (
                status == "open" ||
                status.indexOf("open") !== -1
            ) {

                openCount++;

            }

        }


        points.push(
            "Overall case status: " +
            openCount +
            " case(s) are currently open."
        );


        if (
            rejectedCount > 0
        ) {

            points.push(
                "Attention: " +
                rejectedCount +
                " case(s) contain rejection-related status or stage information."
            );

        }


        points.push(
            "Recommended next step: Review each case individually for its specific requirements or rejection details and consult your assigned international student advisor before making important immigration decisions."
        );


        return points.join(
            "\n"
        );

    }


    // =========================================================
    // FIELD READER
    // =========================================================

    function getField(
        gr,
        fieldNames
    ) {

        if (
            !gr ||
            !fieldNames
        ) {

            return "";

        }


        for (
            var i = 0;
            i < fieldNames.length;
            i++
        ) {

            var field =
                fieldNames[i];


            if (
                gr.isValidField(field)
            ) {

                var value =
                    gr.getDisplayValue(
                        field
                    );


                if (
                    value !== null &&
                    value !== undefined &&
                    String(value).trim() !== ""
                ) {

                    return String(
                        value
                    ).trim();

                }

            }

        }


        return "";
    }


    // =========================================================
    // SAFE VALUE
    // =========================================================

    function safeValue(
        value,
        fallback
    ) {

        if (
            value === null ||
            value === undefined ||
            String(value).trim() === ""
        ) {

            return fallback ||
                "Not available";

        }


        return String(
            value
        );

    }


    // =========================================================
    // QUESTION MATCHING
    // =========================================================

    function containsAny(
        text,
        words
    ) {

        if (!text) {

            return false;

        }


        for (
            var i = 0;
            i < words.length;
            i++
        ) {

            if (
                text.indexOf(
                    words[i]
                ) !== -1
            ) {

                return true;

            }

        }


        return false;

    }


    // =========================================================
    // CONVERT TEXT TO POINTS
    // =========================================================

    function convertToPoints(
        text
    ) {

        if (!text) {

            return [];

        }


        text =
            cleanText(
                text
            );


        var points = [];


        var lines =
            text.split(
                /\r?\n/
            );


        for (
            var i = 0;
            i < lines.length;
            i++
        ) {

            var line =
                String(
                    lines[i]
                ).trim();


            if (!line) {

                continue;

            }


            line =
                line.replace(
                    /^\s*(?:\d+[\.\)]|[-•*])\s*/,
                    ""
                );


            if (!line) {

                continue;

            }


            if (
                line.toLowerCase()
                    .indexOf(
                        "gemini"
                    ) === 0
            ) {

                continue;

            }


            if (
                line.toLowerCase()
                    .indexOf(
                        "knowledge base"
                    ) === 0
            ) {

                continue;

            }


            if (
                line.length > 240
            ) {

                var sentences =
                    line.split(
                        /(?<=[.!?])\s+/
                    );


                for (
                    var j = 0;
                    j < sentences.length;
                    j++
                ) {

                    var sentence =
                        sentences[j].trim();


                    if (
                        sentence.length > 10
                    ) {

                        points.push(
                            sentence
                        );

                    }

                }

            }
            else {

                points.push(
                    line
                );

            }

        }


        var unique = [];

        var seen = {};


        for (
            var k = 0;
            k < points.length;
            k++
        ) {

            var point =
                points[k].trim();


            if (!point) {

                continue;

            }


            var key =
                point.toLowerCase();


            if (!seen[key]) {

                seen[key] = true;

                unique.push(
                    point
                );

            }

        }


        if (
            unique.length > 20
        ) {

            unique =
                unique.slice(
                    0,
                    20
                );

        }


        return unique;

    }


    // =========================================================
    // CLEAN TEXT
    // =========================================================

    function cleanText(
        text
    ) {

        if (!text) {

            return "";

        }


        text =
            String(
                text
            );


        text =
            text.replace(
                /#[a-zA-Z0-9_-]+\s*\{[^}]*\}/g,
                ""
            );


        text =
            text.replace(
                /<style[\s\S]*?<\/style>/gi,
                ""
            );


        text =
            text.replace(
                /<script[\s\S]*?<\/script>/gi,
                ""
            );


        text =
            text.replace(
                /<[^>]+>/g,
                ""
            );


        text =
            text.replace(
                /```/g,
                ""
            );


        text =
            text.replace(
                /\bGemini AI\b/gi,
                ""
            );


        text =
            text.replace(
                /\bGemini\b/gi,
                ""
            );


        text =
            text.replace(
                /\bKnowledge Base\b/gi,
                ""
            );


        text =
            text.replace(
                /[ \t]+/g,
                " "
            );


        text =
            text.replace(
                /\n{3,}/g,
                "\n\n"
            );


        return text.trim();

    }


})();
